require_once __DIR__ . '/_crm.php';
header('Content-Type: application/json; charset=utf-8');
function crm_json(array $d,int $status=200):void{http_response_code($status);echo json_encode($d,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);exit;}
try{$action=(string)($_GET['action']??'');if($action!=='people')crm_json(['ok'=>false,'message'=>'Ação inválida.'],404);$cid=crm_company_id();$q=trim((string)($_GET['q']??''));$where=['company_id=?','active=1','COALESCE(is_customer,0)=1'];$p=[$cid];foreach(array_slice(preg_split('/\s+/u',$q,-1,PREG_SPLIT_NO_EMPTY)?:[],0,6) as $t){$like=nexa_search_like($t);$where[]='(name LIKE ? OR fantasy_name LIKE ? OR document LIKE ? OR phone LIKE ? OR whatsapp LIKE ? OR email LIKE ? OR address LIKE ? OR city LIKE ?)';for($i=0;$i<8;$i++)$p[]=$like;}$st=$pdo->prepare('SELECT id,name,fantasy_name,document,phone,whatsapp,email,address,number,complement,district,city,state FROM finance_people WHERE '.implode(' AND ',$where).' ORDER BY name,id LIMIT 100');$st->execute($p);$rows=$st->fetchAll(PDO::FETCH_ASSOC)?:[];foreach($rows as &$r){$parts=[];$street=trim((string)($r['address']??''));$number=trim((string)($r['number']??''));if($street!=='')$parts[]=$street.($number!==''?', '.$number:'');foreach(['complement','district'] as $k){$v=trim((string)($r[$k]??''));if($v!=='')$parts[]=$v;}$city=trim((string)($r['city']??''));$state=trim((string)($r['state']??''));if($city!==''||$state!=='')$parts[]=trim($city.($state!==''?' / '.$state:''));$r['address_full']=implode(' · ',$parts);}unset($r);crm_json(['ok'=>true,'rows'=>$rows]);}catch(Throwable $e){crm_json(['ok'=>false,'message'=>$e->getMessage()],500);}
